class Solution {
    public int longestValidSubstring(String word, List<String> forbidden) {
        Set<String> bad = new HashSet<>(forbidden);
        int n = word.length();
        int[] hit = new int[n];
        Arrays.fill(hit, -1);
        for (int r = 0; r < n; r++)
            for (int L = 1; L <= Math.min(10, r + 1); L++)
                if (bad.contains(word.substring(r - L + 1, r + 1)))
                    hit[r] = Math.max(hit[r], r - L + 1);
        int ans = 0, l = 0;
        for (int r = 0; r < n; r++) {
            l = Math.max(l, hit[r] + 1);
            ans = Math.max(ans, r - l + 1);
        }
        return ans;
    }
}

